import subprocess

def run(args):
    return subprocess.run(["./executable"]+args, capture_output=True, text=True)
for lang in ["bash","sh","zsh","python","perl","c","cpp","go","rust"]:
    # choose code that prints args
    if lang in ["bash","sh","zsh"]:
        code = "echo $@"
    elif lang=="python":
        code = "import sys; print(sys.argv[1:])"
    elif lang=="perl":
        code = "print join(' ', @ARGV)"
    elif lang=="c":
        code = "#include <stdio.h>\nint main(int argc,char**argv){for(int i=1;i<argc;i++)printf(\"%s \",argv[i]);}"
    elif lang=="cpp":
        code = "#include <iostream>\nint main(int argc,char**argv){for(int i=1;i<argc;i++) std::cout<<argv[i]<<\" \";}"
    elif lang=="go":
        code = 'package main\nimport "fmt"\nimport "os"\nfunc main(){fmt.Println(os.Args[1:])}'
    elif lang=="rust":
        code = 'fn main(){let args: Vec<String> = std::env::args().collect(); println!("{:?}", &args[1..])}'
    else:
        code="echo hi"
    r = run([lang,"--code",code,"arg1","arg2"])
    print(f"lang {lang} code {repr(code)[:30]} with arg1 arg2 -> exit {r.returncode} out {repr(r.stdout[:300])} err {repr(r.stderr[:600])}")
    # also test without --code flag: positional
    r2 = run([lang,code,"arg1","arg2"])
    print(f"  positional without flag -> exit {r2.returncode} out {repr(r2.stdout[:300])} err {repr(r2.stderr[:600])}")

